{"path":"server/dist/server.js","physical_source":"server/dist/server.js","source":"npm:@earendil-works/pi-server@1.1.0/dist/server.js","start":3051,"end":3910,"line":76,"column":9,"physical_line":76,"raw_source":"catch (error) {
            this.closing = true;
            const cleanupErrors = [];
            const listenerResults = await Promise.allSettled(started.map((listener) => listener.close()));
            for (const result of listenerResults) {
                if (result.status === "rejected")
                    cleanupErrors.push(result.reason);
            }
            try {
                await this.closeServerState();
            }
            catch (cleanupError) {
                cleanupErrors.push(cleanupError);
            }
            if (cleanupErrors.length > 0) {
                const failure = new AggregateError([error, ...cleanupErrors], "Server startup and cleanup failed");
                this.settleClosed(failure);
                throw failure;
            }
            this.settleClosed();
            throw error;
        }"}

